head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";

// 발행기관  정보 조회 하는 팝업

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        txb_TITLE.hide();
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");
        const fn_GetPar = parentWin.fn_GetParam;
        if (fn_GetPar !== undefined) {
            fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
            //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

            if (scwin.param1 === "GOVBND_ISUR_CD") {
                // 국채발행체코드
                txb_TITLE.setValue("※ 국채기관코드");
                $c.cm.setColumnProp(grd_Grid, "C", "Name", "국채;기관코드");
                $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
                $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
                $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
            } else if (scwin.param1 === "MUNIBND_ISUR_CD") {
                // 지방채발행체코드
                txb_TITLE.setValue("※ 지방채기관코드");
                $c.cm.setColumnProp(grd_Grid, "C", "Name", "지방채;기관코드");
                $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
                $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
                $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
            } else if (scwin.param1 === "SPECLBND_ISUR_CD") {
                // 특수채발행체코드
                txb_TITLE.setValue("※ 특수채기관코드");
                $c.cm.setColumnProp(grd_Grid, "C", "Name", "특수채;기관코드");
                $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
                $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
                $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
            } else if (scwin.param1 === "BENFCERT_ISUR_CD") {
                // 수익증권발행체코드
                txb_TITLE.setValue("※ 수익증권기관코드");
                $c.cm.setColumnProp(grd_Grid, "C", "Name", "수익증권;기관코드");
                $c.cm.setColumnProp(grd_Grid, "E", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "F", "Show", false);
                $c.cm.setColumnProp(grd_Grid, "A", "width", "100");
                $c.cm.setColumnProp(grd_Grid, "B", "width", "270");
                $c.cm.setColumnProp(grd_Grid, "C", "width", "100");
            } else if (scwin.param1 === "WRNT_ISUR_CD") {
                // 파생상품발행기관정보
                txb_content.setValue("목록에 없는 발행기관은 파생상품발행기관관리에서 파생상품기관코드를 신규등록하세요.");
                txb_TITLE.setValue("※ 파생상품발행기관코드");
                $c.cm.setColumnProp(grd_Grid, "C", "Name", "파생상품;발행기관코드;(ETN/ELW)");
            }
            await scwin.ins_search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93700.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93700.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93700.dts_List_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 발행기관 각 코드를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    let queryId = "";
    // 신청자 정보 조회 하는
    // param1 => STD_CD_APPL_ID , ISUR_APPL_ID
    if (scwin.param1 === "GOVBND_ISUR_CD") {
        // 국채발행체코드
        queryId = "lds.ins.corpinfo.select.listGovbndIsurCdInquiry";
    } else if (scwin.param1 === "MUNIBND_ISUR_CD") {
        // 지방채발행체코드
        queryId = "lds.ins.corpinfo.select.listNunibndIsurCdInquiry";
    } else if (scwin.param1 === "SPECLBND_ISUR_CD") {
        // 특수채발행체코드
        queryId = "lds.ins.corpinfo.select.listSpeclbndIsurCdInquiry";
    } else if (scwin.param1 === "BENFCERT_ISUR_CD") {
        // 수익증권발행체코드
        queryId = "lds.ins.corpinfo.select.listBencertbndIsurCdInquiry";
    } else if (scwin.param1 === "WRNT_ISUR_CD") {
        // 파생상품발행기관정보
        queryId = "lds.ins.corpinfo.select.listWrntIsurCdInquiry";
    }

    // alert(queryId);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
